import type { Chapter } from "./timeline";
import MANIFEST from "./media-manifest.json";

/**
 * TKT-76: where journey media comes from and in what order it downloads. Pure, so it is unit-tested.
 * Every file is addressed as "<base>/<file>?v=<content hash>" (from media-manifest.json, regenerated by
 * scripts/home-media/manifest.mjs), so a replaced file gets a new URL and anything cached can be kept for good.
 */
export type Manifest = Record<string, { v: string; bytes: number }>;
export const MEDIA_MANIFEST: Manifest = MANIFEST;

export type Variant = "desktop" | "mobile";

export function mediaUrl(base: string, file: string, manifest: Manifest = MEDIA_MANIFEST): string {
  const m = manifest[file];
  return `${base}/${file}${m ? `?v=${m.v}` : ""}`;
}

export const clipFile = (src: string, variant: Variant) => `${src}-${variant}.mp4`;

export interface PreloadItem { src: string; file: string; bytes: number }

/**
 * Download order: the scroll clips in chapter order, each fetched whole, one at a time, so the clip the visitor
 * meets next is always the one arriving. `first` moves one clip to the front (a /journey#desk link).
 */
export function preloadOrder(chapters: Chapter[], variant: Variant, first?: string, manifest: Manifest = MEDIA_MANIFEST): PreloadItem[] {
  const srcs = [...new Set(chapters.flatMap((c) => (c.kind === "video" ? [c.src] : [])))];
  if (first && srcs.includes(first)) srcs.splice(srcs.indexOf(first), 1), srcs.unshift(first);
  return srcs.map((src) => {
    const file = clipFile(src, variant);
    return { src, file, bytes: manifest[file]?.bytes ?? 0 };
  });
}

/** The start ring: real bytes of the first two clips (what the visitor sees right after "Enter"). */
export function startProgress(items: PreloadItem[], loaded: Record<string, number>): number {
  const head = items.slice(0, 2);
  const total = head.reduce((s, i) => s + i.bytes, 0);
  if (!total) return 0;
  const got = head.reduce((s, i) => s + Math.min(loaded[i.src] ?? 0, i.bytes), 0);
  return Math.min(1, got / total);
}

/** Before its clip has downloaded, a chapter shows its approved still: the first frame early on, the last later. */
export function stillFor(src: string, local: number): string {
  return `${src}-${local < 0.5 ? "first" : "last"}.jpg`;
}
